import {frenchQuestionCases,makeFrenchQuestionSource,questionCopy as T} from './french-questions-content.mjs';
import {newQuestionWork,changeQuestionWork,compareQuestion,questionSheetsView,keepQuestionSheet} from './french-questions-core.mjs';
import {stopSpeech,localVoices,chooseLocalVoice,speechPreferences} from './play-media.mjs';

const visits=new WeakMap(),clone=value=>structuredClone(value),validOwner=value=>typeof value==='string'&&value.trim().length>0;
const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fr=text=>`<span lang="fr">${esc(text)}</span>`;
const button=(attrs,text,primary=false)=>`<button type="button" class="${primary?'primary':'secondary'}" ${attrs}>${esc(text)}</button>`;
const selector=(attr,value)=>`[${attr}="${CSS.escape(String(value))}"]`;
const parcelName=id=>/^[a-d]$/.test(id)?id.toUpperCase():id;
const slot=(source,work)=>({source:clone(source),work:clone(work||newQuestionWork(source)),folds:{},status:'',statusLang:'en',scroll:0});
function visit(book,owner){let v=visits.get(book);if(!v||v.owner!==owner){v={owner,active:false,caseId:frenchQuestionCases[0].id,serial:0,key:'',screen:'draft',card:null,page:0,drafts:new Map(),copies:new Map(),readonly:new Map()};visits.set(book,v);}return v;}
function fresh(v){const source=makeFrenchQuestionSource(v.caseId);if(!source)return false;v.key=`draft-${++v.serial}`;const a=slot(source);Object.assign(a,{ordinal:v.serial,caseId:v.caseId});v.drafts.set(v.key,a);v.screen='draft';v.card=null;return true;}
const current=v=>v.screen==='draft'?v.drafts.get(v.key):v.screen==='card'?v.readonly.get(v.card):null;
export const frenchQuestionsActive=(book,owner)=>validOwner(owner)&&visits.get(book)?.owner===owner&&visits.get(book)?.active===true;
export function openFrenchQuestions(book,owner){if(!validOwner(owner))return false;const v=visit(book,owner);v.active=true;if(v.screen==='draft'&&!current(v))fresh(v);return true;}
export function frenchQuestionsEntry(){return `<aside class="fq-entry">${button('data-rooms-questions',T.label)}</aside>`;}
function hear(text,key){return button(`data-fq-hear="${esc(key)}" data-speak-lang="fr" data-speak="${esc(text)}"`,T.hear);}
function line(words,key,meaning){return `<div class="fq-language-line">${fr(words.fr)}${hear(words.fr,key)}${meaning?`<p class="fq-meaning">${esc(words.en)}</p>`:''}</div>`;}
function parcelArt(p){const fill=p.colour.fr==='bleu'?'#4d82ab':p.colour.fr==='rouge'?'#b65b64':'#b8c4cb';return `<svg viewBox="0 0 150 112" aria-hidden="true" focusable="false"><path d="M18 32 72 13 133 32 133 88 77 107 18 87Z" fill="${fill}" stroke="#263b59" stroke-width="3"/><path d="M18 32 77 52 133 32M77 52v55M47 22l59 20v55M105 23 47 42v55" fill="none" stroke="#f2dfaf" stroke-width="6"/><path d="M18 32 77 52 133 32M77 52v55" fill="none" stroke="#263b59" stroke-width="2"/><circle cx="77" cy="36" r="9" fill="#e7c66d" stroke="#263b59" stroke-width="2"/></svg>`;}
function parcels(a,readonly){const s=a.source,w=a.work,selected=s.parcels.find(p=>p.id===w.selected);return `<section class="fq-cupboard" aria-labelledby="fq-parcels-title"><h3 id="fq-parcels-title">${esc(T.parcels)}</h3><div class="fq-parcel-grid">${s.parcels.map(p=>`<button type="button" class="fq-parcel" data-fq-parcel="${esc(p.id)}" aria-pressed="${p.id===w.selected}"${readonly?' disabled':''}>${parcelArt(p)}<strong>${esc(parcelName(p.id))}</strong><span class="fq-parcel-colour" lang="fr">${esc(p.colour.fr)}</span><span lang="fr">${esc(p.room.fr)}</span>${w.meaningShown?`<span class="fq-meaning">${esc(p.colour.en)} · ${esc(p.room.en)}</span>`:''}</button>`).join('')}</div><p class="fq-chosen" data-fq-chosen>${esc(selected?`${T.chosen}: ${parcelName(selected.id)}`:T.noSelection)}</p></section>`;}
function conversation(a){const s=a.source,w=a.work;return `<section class="fq-conversation" aria-labelledby="fq-conversation-title"><h3 id="fq-conversation-title">${esc(T.conversation)}</h3>${w.asked.length?`<ol data-fq-conversation tabindex="0" aria-label="${esc(T.conversation)}">${w.asked.map((id,index)=>{const q=s.questions.find(q=>q.id===id);return `<li data-fq-exchange="${index}"><div class="fq-your-question"><strong>${esc(T.question)}</strong>${line({fr:q.fr,en:q.en},`question:${q.id}`,w.meaningShown)}</div><div class="fq-reply" data-fq-reply="${index}"><strong>${esc(T.reply)}</strong>${line(q.reply,`reply:${index}`,w.meaningShown)}</div></li>`;}).join('')}</ol>`:`<p data-fq-conversation>${esc(T.noQuestions)}</p>`}</section>`;}
function questions(a,readonly){const w=a.work;return `<section class="fq-questions" aria-labelledby="fq-questions-title"><h3 id="fq-questions-title">${esc(T.questions)}</h3><div class="fq-question-buttons">${a.source.questions.map(q=>`<div class="fq-question-option"><button type="button" data-fq-ask="${esc(q.id)}"${readonly?' disabled':''}><span lang="fr">${esc(q.fr)}</span></button>${hear(q.fr,`question:${q.id}`)}${w.meaningShown?`<p class="fq-meaning">${esc(q.en)}</p>`:''}</div>`).join('')}</div>${w.asked.length>=32?`<p class="fq-limit">${esc(T.historyFull)}</p>`:''}</section>`;}
function comparison(a){const w=a.work;if(!w.compared)return '';const result=compareQuestion(a.source,w);return `<section class="fq-comparison" data-fq-comparison><h3>${esc(T.comparisonOpened)}</h3><p class="fq-reference-labels">${fr(result.target.colour.fr)} · ${fr(result.target.room.fr)}${w.meaningShown?`<span class="fq-meaning">${esc(result.target.colour.en)} · ${esc(result.target.room.en)}</span>`:''}</p><p>${esc(result.selected?`${T.chosen}: ${parcelName(result.selected.id)}`:T.noSelection)}</p>${result.selected?`<p>${fr(result.selected.colour.fr)} · ${fr(result.selected.room.fr)}${w.meaningShown?`<span class="fq-meaning">${esc(result.selected.colour.en)} · ${esc(result.selected.room.en)}</span>`:''}</p><p class="fq-comparison-result">${esc(result.matches?T.match:T.different)}</p>`:''}</section>`;}
function fold(a,key,title,body){return `<details data-fq-fold="${key}"${a.folds[key]?' open':''}><summary>${esc(title)}</summary>${body}</details>`;}
function activity(a,readonly){const s=a.source,w=a.work;return `<h2 id="fq-title" tabindex="-1" lang="fr">${esc(s.title)}</h2>${w.meaningShown?`<p class="fq-meaning">${esc(s.titleMeaning)}</p>`:''}${readonly?`<p class="fq-kept">${esc(T.readOnly)}</p>${button('data-fq-copy',T.copy)}`:''}<p class="fq-instruction">${esc(T.instruction)}</p><section class="fq-note">${line(s.note,'note',w.meaningShown)}</section><div class="fq-instrument"><div class="fq-talk">${conversation(a)}${questions(a,readonly)}</div>${parcels(a,readonly)}</div><div class="fq-actions">${button(`data-fq-meaning aria-pressed="${w.meaningShown}"${readonly?' disabled':''}`,T.meanings)}${button(`data-fq-compare${readonly?' disabled':''}`,T.compare)}${!readonly?button('data-fq-keep',T.keep,true):''}</div>${comparison(a)}${fold(a,'teaching','How the questions help',`<p>${esc(T.teaching)}</p><p>${esc(T.workedExample)}</p>${line(s.example,'example',w.meaningShown)}`)}<p id="fq-status" role="status" aria-live="polite" tabindex="-1" lang="${a.statusLang==='fr'?'fr':'en'}">${esc(a.status)}</p>`;}
function shelf(book,v){const view=questionSheetsView(book),items=view.items;v.page=Math.max(0,Math.min(v.page,Math.max(0,Math.ceil(items.length/8)-1)));return `<h2 id="fq-title" tabindex="-1">${esc(T.shelf)}</h2>${view.status==='unavailable'?`<p>${esc(T.unreadable)}</p>`:!items.length?`<p>${esc(T.emptyShelf)}</p>`:`<ol class="fq-sheets" start="${v.page*8+1}">${items.slice(v.page*8,v.page*8+8).map(item=>`<li>${item.readable?`<button type="button" data-fq-card="${item.id}"><span lang="fr">${esc(item.raw.source.title)}</span></button>`:`<p>${esc(T.unreadable)}</p>`}</li>`).join('')}</ol><div class="fq-actions">${button(`data-fq-earlier${v.page===0?' disabled':''}`,T.earlier)}${button(`data-fq-later${(v.page+1)*8>=items.length?' disabled':''}`,T.later)}</div>`}<p id="fq-status" role="status" aria-live="polite" tabindex="-1"></p>`;}
export function frenchQuestionsPage(book,owner){const v=visit(book,owner);if(v.screen==='draft'&&!current(v))fresh(v);if(v.screen==='card'){const row=questionSheetsView(book).items.find(item=>item.readable&&item.id===v.card),prior=v.readonly.get(v.card);if(row&&(!prior||prior.raw!==row.raw||prior.rawBytes!==JSON.stringify(row.raw))){const bytes=JSON.stringify(row.raw),a=slot(row.raw.source,row.raw.work);if(prior?.rawBytes===bytes){a.folds={...prior.folds};a.scroll=prior.scroll;}Object.assign(a,{raw:row.raw,rawBytes:bytes});v.readonly.set(v.card,a);}else if(!row)v.readonly.delete(v.card);}const a=current(v);return `<section class="fq-page" data-fq-root><header><div class="fq-nav">${button('data-fq-back',T.back)}${button('data-fq-working',T.working)}${button('data-fq-shelf',T.shelf)}</div><h1 id="fq-heading" tabindex="-1">${esc(T.label)}</h1><p>${esc(T.story)}</p></header>${v.screen==='shelf'?shelf(book,v):a?activity(a,v.screen==='card'):`<h2 id="fq-title" tabindex="-1">${esc(T.unreadable)}</h2><p id="fq-status" role="status" tabindex="-1"></p>`}<div class="fq-visits"><label>${esc(T.visit)}<select data-fq-case lang="fr">${frenchQuestionCases.map(c=>`<option value="${esc(c.id)}"${c.id===v.caseId?' selected':''}>${esc(c.title)}</option>`).join('')}</select></label>${button('data-fq-fresh',T.fresh)}<label>${esc(T.drafts)}<select data-fq-draft>${[...v.drafts].map(([id,draft])=>`<option value="${esc(id)}"${id===v.key?' selected':''}>${esc(draft.source.title)} · ${draft.ordinal}</option>`).join('')}</select></label></div><footer><p>${esc(T.spokenInvitation)}</p><a href="#notes">Notes and download</a><details data-fq-grownup><summary>For grown-ups</summary><p>${esc(T.qualification)}</p><p>${esc(T.speechNotice)}</p><p>${esc(T.keptExplanation)}</p></details></footer></section>`;}

export function bindFrenchQuestions(book,ctx={}){const owner=()=>typeof ctx.explorerId==='function'?ctx.explorerId():null,v=visits.get(book),root=document.querySelector('[data-fq-root]');if(!root||!v)return;const a=current(v),screen=v.screen,key=v.key,card=v.card,source=a?.source,route=location.hash,notebook=ctx.notebook,explorerId=ctx.explorerId,isActive=ctx.isActive,canExport=ctx.canExport,parents=new WeakMap(),speechText=new WeakMap();let expected=a?.work,sourceBytes,workBytes,rawRoot,rawBytes,rootPresent,snapshotOK=false;
 const adopt=()=>{try{expected=a?.work;sourceBytes=JSON.stringify(source);workBytes=JSON.stringify(expected);rawRoot=book.frenchQuestionSheets;rawBytes=JSON.stringify(rawRoot);rootPresent=Object.hasOwn(book,'frenchQuestionSheets');snapshotOK=true;}catch{snapshotOK=false;}};adopt();
 const chain=n=>{const rows=[];for(let p=n;p&&p!==document;p=p.parentNode)rows.push([p,p.parentNode]);return rows;},rootChain=chain(root),unchanged=rows=>rows.every(([node,parent])=>node.parentNode===parent);
 const visible=n=>{try{for(let p=n;p;p=p.parentElement){if(p.hidden||p.getAttribute?.('aria-hidden')==='true'||getComputedStyle(p).display==='none'||getComputedStyle(p).visibility==='hidden')return false;if(p.tagName==='DETAILS'&&!p.open&&p!==n){const summary=[...p.children].find(child=>child.tagName==='SUMMARY');if(!summary?.contains(n))return false;}}return true;}catch{return false;}};
 const attached=n=>{try{return snapshotOK&&visits.get(book)===v&&validOwner(owner())&&frenchQuestionsActive(book,owner())&&typeof notebook==='function'&&typeof explorerId==='function'&&typeof isActive==='function'&&typeof canExport==='function'&&ctx.notebook===notebook&&ctx.explorerId===explorerId&&ctx.isActive===isActive&&ctx.canExport===canExport&&notebook()===book&&isActive()===true&&location.hash===route&&route==='#learn/french'&&root.isConnected&&document.querySelector('[data-fq-root]')===root&&unchanged(rootChain)&&n.isConnected&&root.contains(n)&&parents.has(n)&&unchanged(parents.get(n))&&v.screen===screen&&v.key===key&&v.card===card&&current(v)===a&&a?.source===source&&a?.work===expected&&JSON.stringify(source)===sourceBytes&&JSON.stringify(expected)===workBytes&&Object.hasOwn(book,'frenchQuestionSheets')===rootPresent&&book.frenchQuestionSheets===rawRoot&&JSON.stringify(rawRoot)===rawBytes&&(screen!=='card'||!!a?.raw&&questionSheetsView(book).items.some(row=>row.readable&&row.id===card&&row.raw===a.raw&&JSON.stringify(row.raw)===a.rawBytes));}catch{return false;}};
 const live=n=>attached(n)&&visible(n),guard=n=>{parents.set(n,chain(n));for(const type of ['click','input','change','toggle','keydown','focusin'])n.addEventListener(type,e=>{if(!live(n)){e.preventDefault();e.stopImmediatePropagation();}},true);};guard(root);root.querySelectorAll('button,a,select,details,summary').forEach(guard);root.querySelectorAll('[data-fq-hear]').forEach(n=>speechText.set(n,n.dataset.speak));
 const focus=target=>{const next=document.querySelector('[data-fq-root]'),node=next?.querySelector(target);(node&&!node.disabled&&visible(node)?node:next?.querySelector('#fq-title'))?.focus({preventScroll:true});},redraw=(target='#fq-title')=>{ctx.render?.();const next=current(v),log=document.querySelector('[data-fq-root] ol[data-fq-conversation]');if(next&&log){log.scrollTop=Number.isFinite(next.scroll)?next.scroll:log.scrollHeight;next.scroll=log.scrollTop;}focus(target);};
 const folds=()=>{if(a){a.scroll=root.querySelector('ol[data-fq-conversation]')?.scrollTop||0;root.querySelectorAll('[data-fq-fold]').forEach(n=>{if(attached(n))a.folds[n.dataset.fqFold]=n.open;});}};
 const clear=()=>{if(a){a.status='';a.statusLang='en';}const node=root.querySelector('#fq-status');if(node)node.textContent='';};
 const status=message=>{if(a){a.status=message;a.statusLang='en';}const node=root.querySelector('#fq-status');if(node){node.lang='en';node.textContent=message;node.focus({preventScroll:true});}};
 function change(action,value){if(screen!=='draft'||!a)return false;const next=changeQuestionWork(source,a.work,action,value);if(!next)return false;a.work=next;adopt();return true;}
 function on(query,fn,target='#fq-title'){root.querySelectorAll(query).forEach(n=>n.addEventListener('click',()=>{if(!live(n)||n.disabled)return;folds();clear();stopSpeech();if(fn(n)!==false)redraw(typeof target==='function'?target(n):target);}));}
 on('[data-fq-back]',()=>{v.active=false;ctx.render?.();const heading=document.querySelector('#rooms-heading');heading?.focus();return false;});
 on('[data-fq-working]',()=>{if(!v.drafts.has(v.key))fresh(v);v.screen='draft';v.card=null;});on('[data-fq-shelf]',()=>{v.screen='shelf';v.card=null;});on('[data-fq-card]',n=>{const id=Number(n.dataset.fqCard);if(!questionSheetsView(book).items.some(row=>row.readable&&row.id===id))return false;v.card=id;v.screen='card';});on('[data-fq-earlier]',()=>{v.page--;},'[data-fq-later]');on('[data-fq-later]',()=>{v.page++;},'[data-fq-earlier]');
 on('[data-fq-ask]',n=>{if(a.work.asked.length>=32){status(T.historyFull);return false;}if(!change('ask',n.dataset.fqAsk))return false;a.scroll=null;a.status=source.questions.find(q=>q.id===n.dataset.fqAsk).reply.fr;a.statusLang='fr';return true;},n=>selector('data-fq-ask',n.dataset.fqAsk));
 on('[data-fq-parcel]',n=>change('select',n.dataset.fqParcel),n=>selector('data-fq-parcel',n.dataset.fqParcel));
 on('[data-fq-meaning]',()=>change('meaning'),'[data-fq-meaning]');
 on('[data-fq-compare]',()=>{if(a.work.selected===null){status(T.chooseFirst);return false;}return change('compare');},'[data-fq-compare]');
 on('[data-fq-fresh]',()=>fresh(v));
 root.querySelector('[data-fq-case]')?.addEventListener('change',e=>{const n=e.currentTarget;if(!live(n)||!frenchQuestionCases.some(c=>c.id===n.value))return;folds();clear();stopSpeech();v.caseId=n.value;const prior=[...v.drafts].findLast(([,draft])=>draft.caseId===v.caseId);if(prior){v.key=prior[0];v.screen='draft';v.card=null;}else fresh(v);redraw('[data-fq-case]');});
 root.querySelector('[data-fq-draft]')?.addEventListener('change',e=>{const n=e.currentTarget;if(!live(n)||!v.drafts.has(n.value))return;folds();clear();stopSpeech();v.key=n.value;v.screen='draft';v.card=null;redraw('[data-fq-draft]');});
 on('[data-fq-copy]',()=>{if(screen!=='card'||!a?.raw)return false;let draftId=v.copies.get(card);if(!draftId||!v.drafts.has(draftId)){draftId=`draft-${++v.serial}`;const copy=slot(a.raw.source,a.raw.work);Object.assign(copy,{ordinal:v.serial,folds:{...a.folds},scroll:a.scroll});v.drafts.set(draftId,copy);v.copies.set(card,draftId);}v.key=draftId;v.screen='draft';v.card=null;});
 on('[data-fq-keep]',()=>{if(screen!=='draft'||!a)return false;const id=keepQuestionSheet(book,source,a.work,{canExport});if(!id){status(T.refused);return false;}adopt();try{ctx.save?.();}catch{}const row=questionSheetsView(book).items.find(row=>row.readable&&row.id===id);if(!row)return false;const kept=slot(row.raw.source,row.raw.work);Object.assign(kept,{folds:{...a.folds},scroll:a.scroll,raw:row.raw,rawBytes:JSON.stringify(row.raw),status:T.kept});v.readonly.set(id,kept);v.card=id;v.screen='card';v.page=Math.floor(row.index/8);},'#fq-status');
 root.querySelectorAll('[data-fq-fold]').forEach(n=>n.addEventListener('toggle',()=>{if(live(n)&&a){stopSpeech();a.folds[n.dataset.fqFold]=n.open;}}));
 root.addEventListener('click',event=>{const n=event.target.closest?.('[data-fq-hear]');if(!n||!root.contains(n))return;if(!live(n)){event.preventDefault();event.stopImmediatePropagation();return;}folds();clear();stopSpeech();let available=false;try{const voices=window.speechSynthesis?.getVoices?.()||[];available=typeof window.SpeechSynthesisUtterance==='function'&&typeof window.speechSynthesis?.speak==='function'&&localVoices(voices,'fr').length>0&&!!chooseLocalVoice(voices,speechPreferences().voice,'fr');}catch{}if(!available){event.preventDefault();event.stopImmediatePropagation();status(T.noVoice);return;}if(screen==='draft'&&!change('speech')){event.preventDefault();event.stopImmediatePropagation();return;}n.dataset.speak=speechText.get(n);n.dataset.speakLang='fr';adopt();},true);
 root.querySelectorAll('a,summary').forEach(n=>n.addEventListener('click',()=>{if(live(n)){clear();stopSpeech();}}));
}
